export function gridToRgba(grid, palette = PALETTE) {
  const height = grid.length;
  const width = grid[0]?.length ?? 0;
  if (height === 0 || width === 0) throw new Error('grid must not be empty');
  const data = new Uint8ClampedArray(width * height * 4);
  grid.forEach((row, y) => {
    if (row.length !== width) throw new Error(`row ${y} has width ${row.length}, expected ${width}`);
    row.forEach((idx, x) => {
      if (!Number.isInteger(idx) || idx < 0 || idx >= palette.length) throw new Error(`palette index out of range: ${idx} at (${x},${y})`);
      const hex = palette[idx];
      const o = (y * width + x) * 4;
      data[o] = parseInt(hex.slice(1, 3), 16);
      data[o + 1] = parseInt(hex.slice(3, 5), 16);
      data[o + 2] = parseInt(hex.slice(5, 7), 16);
      data[o + 3] = 255;
    });
  });
  return { width, height, data };
}

export function buildSpriteSheet(frames) {
  if (frames.length === 0) throw new Error('frames must not be empty');
  const { width: fw, height: fh } = frames[0];
  const n = frames.length;
  const width = fw * n;
  const data = new Uint8ClampedArray(width * fh * 4);
  frames.forEach((f, i) => {
    if (f.width !== fw || f.height !== fh) throw new Error(`frame ${i} is ${f.width}x${f.height}, expected ${fw}x${fh}`);
    for (let y = 0; y < fh; y++) data.set(f.data.subarray(y * fw * 4, (y + 1) * fw * 4), (y * width + i * fw) * 4);
  });
  return { width, height: fh, frameWidth: fw, frameHeight: fh, frameCount: n, data };
}
